import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    static int n;
    static int[] bad;

    static int dfs(int idx, int forbiddenMask) {
        if (idx == n) {
            return 1;
        }

        // Opção 1: não incluir o ingrediente idx
        int count = dfs(idx + 1, forbiddenMask);

        // Opção 2: incluir o ingrediente idx, se permitido
        if ((forbiddenMask & (1 << idx)) == 0) {
            count += dfs(idx + 1, forbiddenMask | bad[idx]);
        }

        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = null;

        String line = reader.readLine();
        if (line == null) return;
        tokenizer = new StringTokenizer(line);
        n = Integer.parseInt(tokenizer.nextToken());
        int m = Integer.parseInt(tokenizer.nextToken());

        bad = new int[n];
        for (int i = 0; i < m; i++) {
            line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            if (line == null) break;
            tokenizer = new StringTokenizer(line);
            int u = Integer.parseInt(tokenizer.nextToken()) - 1;
            int v = Integer.parseInt(tokenizer.nextToken()) - 1;
            bad[u] |= (1 << v);
            bad[v] |= (1 << u);
        }

        // dfs retorna o número de combinações válidas incluindo o conjunto vazio
        int total = dfs(0, 0) - 1;

        System.out.println(total);
    }
}
